import type DOMPurify from "dompurify";

let sanitizeFn: typeof DOMPurify.sanitize | undefined;
let sanitizePromise: Promise<typeof DOMPurify.sanitize> | undefined;

const getSanitize = async () => {
	if (!sanitizePromise) {
		sanitizePromise = import("dompurify").then(({ default: DOMPurify }) => {
			sanitizeFn = DOMPurify.sanitize;
			return DOMPurify.sanitize;
		});
	}

	return sanitizePromise;
};

const sanitizeMarkup = (
	sanitize: typeof DOMPurify.sanitize,
	markup?: string | number | null,
) => sanitize(String(markup ?? ""), { USE_PROFILES: { html: true, svg: true } });

export const preloadSanitizeHtml = async () => {
	await getSanitize();
};

export const sanitizeHtml = async (markup?: string | number | null) =>
	sanitizeMarkup(await getSanitize(), markup);

export const sanitizeHtmlSync = (markup?: string | number | null) => {
	if (!sanitizeFn) {
		throw new Error("sanitizeHtmlSync called before preloadSanitizeHtml");
	}

	return sanitizeMarkup(sanitizeFn, markup);
};
